internal object StoryLibraryBatch75 {
    val stories = listOf(
        StorySeries(
            id = "museum_of_borrowed_time",
            title = "The Museum of Borrowed Time",
            tagline = "A ten-part story of memory, discovery, and community.",
            parts = listOf(
                StoryPart(1, "The Unlabelled Clock", listOf("At the town museum, Dara found a clock with no label. It was kept in a cabinet of objects whose histories were incomplete.", "The curator said the clock had been donated with a note asking that it be displayed only when its story was known.", "Dara joined the student volunteer team to trace its history.")),
                StoryPart(2, "A Photograph", listOf("An old photograph showed the same clock above the doorway of a railway waiting room. A date on the back led Dara to the public newspaper archive.", "The article described a station renovation and thanked local volunteers who had kept the waiting room open during the work.", "One volunteer was named as clockkeeper: Mr Ibe.")),
                StoryPart(3, "The Clockkeeper", listOf("Mr Ibe was now retired and living nearby. He remembered winding the clock every morning and checking that passengers could read it from the platform.", "He explained that the clock had run several minutes fast, so he kept a handwritten correction card beside it.", "Dara wondered why the museum had received it without those details.")),
                StoryPart(4, "A Missing Card", listOf("The curator searched the donation file and found that the correction card had been listed separately. It had never arrived at the museum.", "The card might have been packed with station documents stored at the transport archive.", "Dara and the curator arranged a supervised visit and checked the public catalogue.")),
                StoryPart(5, "The Archive Box", listOf("Inside the archive box they found station plans, staff photographs, and a small envelope marked 'time notes'. The correction card was inside.", "It listed dates when the clock had been adjusted and named the volunteers who helped maintain the waiting room.", "Dara realised the clock's story belonged to a group, not only to Mr Ibe.")),
                StoryPart(6, "The Disagreement", listOf("The museum board wanted to display the clock as an example of railway technology. Dara argued that the volunteers' work mattered too.", "The curator suggested a label with two sections: how the clock worked and how people used it.", "They interviewed former passengers and gathered permission to include their memories.")),
                StoryPart(7, "A Living Record", listOf("Several residents remembered meeting relatives beneath the clock. One described how the correction card helped people avoid missing an important connection.", "The museum checked dates against its archive and marked personal memories clearly as recollections.", "Dara wrote a draft that distinguished documented facts from stories shared by residents.")),
                StoryPart(8, "The Exhibition Plan", listOf("The curator approved a display with the clock, correction card, station photograph, and a listening station for recorded memories.", "Mr Ibe reviewed the text and corrected a date. Dara welcomed the correction and updated the label before printing.", "The student team created a timeline showing how the station and neighbourhood had changed.")),
                StoryPart(9, "Opening Day", listOf("Former railway workers attended the exhibition. Mr Ibe explained the daily routine of checking the clock, while younger visitors asked how mechanical timepieces were maintained.", "The display attracted more interest than expected because it connected a familiar object with everyday community work.", "Dara added a visitors' notebook so people could share further memories or corrections.")),
                StoryPart(10, "Time Well Kept", listOf("The clock became the centrepiece of a new exhibition about public places and the people who cared for them.", "The museum digitised the correction card and returned the original to secure storage. Mr Ibe donated a photograph of the volunteer team.", "Dara learned that time was measured by clocks, but remembered through the people who shared it."))
            )
        )
    )
}
